#!/usr/bin/env python3
from pathlib import Path
import sys

if len(sys.argv)!=5:
    raise SystemExit("usage: patch.py SRC_CTL LIVE_CTL SRC_UI LIVE_UI")

src_ctl,live_ctl,src_ui,live_ui=map(Path,sys.argv[1:])
BACKEND='\n# >>> HYPER-HOST SQL ACCESS PANEL v1 >>>\nimport ipaddress as _sqlacc_ipaddress\nimport subprocess as _sqlacc_subprocess\n\ndef _sqlacc_mysql_service():\n    for svc in (\'mariadb\',\'mysql\'):\n        cp=_sqlacc_subprocess.run(\n            [\'systemctl\',\'list-unit-files\',svc+\'.service\',\'--no-legend\'],\n            stdout=_sqlacc_subprocess.PIPE,stderr=_sqlacc_subprocess.DEVNULL,text=True\n        )\n        if svc+\'.service\' in cp.stdout:\n            return svc\n    return \'mariadb\'\n\ndef _sqlacc_bind_file():\n    for root in (\'/etc/mysql/mariadb.conf.d\',\'/etc/mysql/mysql.conf.d\'):\n        p=Path(root)\n        if p.is_dir():\n            return p/\'99-hyper-cs16-external.cnf\'\n    p=Path(\'/etc/mysql/mariadb.conf.d\')\n    p.mkdir(parents=True,exist_ok=True)\n    return p/\'99-hyper-cs16-external.cnf\'\n\ndef _sqlacc_ufw_active():\n    try:\n        cp=_sqlacc_subprocess.run(\n            [\'ufw\',\'status\'],stdout=_sqlacc_subprocess.PIPE,\n            stderr=_sqlacc_subprocess.DEVNULL,text=True,timeout=10\n        )\n        return cp.returncode==0 and \'Status: active\' in cp.stdout\n    except Exception:\n        return False\n\ndef _sqlacc_ufw_delete(ip:str):\n    if not ip or not _sqlacc_ufw_active():\n        return False\n    _sqlacc_subprocess.run(\n        [\'ufw\',\'--force\',\'delete\',\'allow\',\'from\',ip,\'to\',\'any\',\'port\',\'3306\',\'proto\',\'tcp\'],\n        stdout=_sqlacc_subprocess.DEVNULL,stderr=_sqlacc_subprocess.DEVNULL,timeout=20\n    )\n    return True\n\ndef _sqlacc_ufw_allow(ip:str):\n    if not _sqlacc_ufw_active():\n        return False\n    cp=_sqlacc_subprocess.run(\n        [\'ufw\',\'allow\',\'from\',ip,\'to\',\'any\',\'port\',\'3306\',\'proto\',\'tcp\'],\n        stdout=_sqlacc_subprocess.PIPE,stderr=_sqlacc_subprocess.PIPE,text=True,timeout=20\n    )\n    if cp.returncode!=0:\n        raise RuntimeError(\'UFW: \'+(cp.stderr.strip() or cp.stdout.strip()))\n    return True\n\ndef _sqlacc_restart_mysql():\n    svc=_sqlacc_mysql_service()\n    cp=_sqlacc_subprocess.run(\n        [\'systemctl\',\'restart\',svc],\n        stdout=_sqlacc_subprocess.PIPE,stderr=_sqlacc_subprocess.PIPE,text=True,timeout=60\n    )\n    if cp.returncode!=0:\n        raise RuntimeError(\'Не удалось перезапустить \'+svc+\': \'+(cp.stderr.strip() or cp.stdout.strip()))\n    return svc\n\ndef _sqlacc_listen_3306():\n    try:\n        cp=_sqlacc_subprocess.run(\n            [\'ss\',\'-ltn\'],stdout=_sqlacc_subprocess.PIPE,\n            stderr=_sqlacc_subprocess.DEVNULL,text=True,timeout=10\n        )\n        for line in cp.stdout.splitlines():\n            if \':3306\' in line:\n                return True\n    except Exception:\n        pass\n    return False\n\ndef _sqlacc_any_external(except_sid:int|None=None):\n    root=Path(\'/var/lib/hyper-cs16/servers\')\n    if not root.is_dir():\n        return False\n    for p in root.glob(\'*.json\'):\n        try:\n            d=json.loads(p.read_text(encoding=\'utf-8\'))\n            if except_sid is not None and int(d.get(\'id\') or 0)==int(except_sid):\n                continue\n            if bool(d.get(\'sql_external_enabled\')) and str(d.get(\'sql_external_ip\') or \'\').strip():\n                return True\n        except Exception:\n            pass\n    return False\n\ndef sql_external_status(sid:int):\n    c=load_server(sid)\n    db_name=str(c.get(\'sql_db\') or \'\')\n    db_user=str(c.get(\'sql_user\') or \'\')\n    pw=str(c.get(\'sql_password\') or \'\')\n    try:\n        rt=load_runtime()\n    except Exception:\n        rt={}\n    public_ip=str(c.get(\'public_ip\') or rt.get(\'public_ip\') or \'\')\n    return {\n        \'ok\':True,\n        \'id\':sid,\n        \'provisioned\':bool(db_name and db_user and pw),\n        \'enabled\':bool(c.get(\'sql_external_enabled\')),\n        \'remote_ip\':str(c.get(\'sql_external_ip\') or \'\'),\n        \'database\':db_name,\n        \'user\':db_user,\n        \'public_host\':public_ip,\n        \'port\':3306,\n        \'bind_file\':str(_sqlacc_bind_file()),\n        \'bind_managed\':_sqlacc_bind_file().is_file(),\n        \'listening\':_sqlacc_listen_3306(),\n        \'ufw_active\':_sqlacc_ufw_active(),\n        \'phpmyadmin_url\':\'/phpmyadmin/\'\n    }\n\ndef sql_external_enable(sid:int,remote_ip:str):\n    require_root()\n    c=load_server(sid)\n    db_name=str(c.get(\'sql_db\') or \'\')\n    db_user=str(c.get(\'sql_user\') or \'\')\n    password=str(c.get(\'sql_password\') or \'\')\n    if not (db_name and db_user and password):\n        raise RuntimeError(\'SQL этого сервера ещё не создан. Сначала нажми «Подключить / восстановить SQL».\')\n    if not re.fullmatch(r\'[A-Za-z0-9_]{1,64}\',db_name) or not re.fullmatch(r\'[A-Za-z0-9_]{1,64}\',db_user):\n        raise RuntimeError(\'Некорректное имя SQL базы/пользователя\')\n\n    remote=str(remote_ip or \'\').strip()\n    try:\n        addr=_sqlacc_ipaddress.ip_address(remote)\n        if addr.version!=4:\n            raise ValueError()\n    except Exception:\n        raise RuntimeError(\'Укажи один точный IPv4 адрес, например 1.2.3.4\')\n    if addr.is_unspecified or addr.is_multicast:\n        raise RuntimeError(\'Этот IP использовать нельзя\')\n\n    old_ip=str(c.get(\'sql_external_ip\') or \'\').strip()\n\n    qdb=\'`\'+db_name+\'`\'\n    quser=_sql_literal(db_user)\n    qpass=_sql_literal(password)\n    qhost=_sql_literal(remote)\n\n    sql=(\n        f"CREATE USER IF NOT EXISTS {quser}@{qhost} IDENTIFIED BY {qpass};"\n        f"ALTER USER {quser}@{qhost} IDENTIFIED BY {qpass};"\n        f"GRANT ALL PRIVILEGES ON {qdb}.* TO {quser}@{qhost};"\n        "FLUSH PRIVILEGES;"\n    )\n    _mysql_root_exec(sql)\n\n    if old_ip and old_ip!=remote:\n        try:\n            _mysql_root_exec(f"DROP USER IF EXISTS {quser}@{_sql_literal(old_ip)};FLUSH PRIVILEGES;")\n        except Exception:\n            pass\n        _sqlacc_ufw_delete(old_ip)\n\n    conf=_sqlacc_bind_file()\n    conf.write_text(\n        \'# HYPER-HOST managed external SQL access\\n\'\n        \'[mysqld]\\n\'\n        \'bind-address = 0.0.0.0\\n\',\n        encoding=\'utf-8\'\n    )\n    os.chmod(conf,0o644)\n    svc=_sqlacc_restart_mysql()\n    if not _sqlacc_listen_3306():\n        raise RuntimeError(\'MariaDB/MySQL перезапущен, но TCP/3306 не слушается. Проверь skip-networking в конфиге.\')\n\n    fw=_sqlacc_ufw_allow(remote)\n    c[\'sql_external_enabled\']=True\n    c[\'sql_external_ip\']=remote\n    c[\'sql_external_updated_at\']=int(time.time())\n    save_server(c)\n\n    st=sql_external_status(sid)\n    st.update({\'db_service\':svc,\'ufw_managed\':fw})\n    return st\n\ndef sql_external_disable(sid:int):\n    require_root()\n    c=load_server(sid)\n    db_user=str(c.get(\'sql_user\') or \'\')\n    old_ip=str(c.get(\'sql_external_ip\') or \'\').strip()\n\n    if db_user and old_ip and re.fullmatch(r\'[A-Za-z0-9_]{1,64}\',db_user):\n        try:\n            _mysql_root_exec(\n                f"DROP USER IF EXISTS {_sql_literal(db_user)}@{_sql_literal(old_ip)};"\n                "FLUSH PRIVILEGES;"\n            )\n        except Exception:\n            pass\n    _sqlacc_ufw_delete(old_ip)\n\n    c[\'sql_external_enabled\']=False\n    c[\'sql_external_ip\']=\'\'\n    c[\'sql_external_updated_at\']=int(time.time())\n    save_server(c)\n\n    if not _sqlacc_any_external(except_sid=sid):\n        conf=_sqlacc_bind_file()\n        try:\n            conf.unlink()\n        except FileNotFoundError:\n            pass\n        _sqlacc_restart_mysql()\n\n    return sql_external_status(sid)\n# <<< HYPER-HOST SQL ACCESS PANEL v1 <<<\n'
POSTS="        if($action==='sql_external_enable'){\n            $id=(int)($_POST['id']??0);\n            require_perm('sql.manage',$id);\n            server_row($id);\n            $remote=trim((string)($_POST['remote_ip']??''));\n            $r=ctl(['sql-external-enable',$id,'--remote',$remote],120);\n            if(empty($r['ok']))throw new RuntimeException(ctl_error($r,'Не удалось включить внешний SQL'));\n            audit('sql_external_enable','remote='.$remote,$id);\n            flash('Внешний SQL включён только для IP '.$remote.'. Host: '.(string)($r['public_host']??'').':3306');\n            redirect('/?page=sql&server_id='.$id);\n        }\n        if($action==='sql_external_disable'){\n            $id=(int)($_POST['id']??0);\n            require_perm('sql.manage',$id);\n            server_row($id);\n            $r=ctl(['sql-external-disable',$id],120);\n            if(empty($r['ok']))throw new RuntimeException(ctl_error($r,'Не удалось отключить внешний SQL'));\n            audit('sql_external_disable','',$id);\n            flash('Внешний SQL отключён. Внешний MySQL grant удалён.');\n            redirect('/?page=sql&server_id='.$id);\n        }\n"
CARD='\n<?php if(can_perm(\'sql.manage\',$sidFilter)):\n$sqlExt=ctl([\'sql-external-status\',$sidFilter],20);\n?>\n<div class="panel-card">\n  <div class="panel-head">\n    <div>\n      <h2><i class="fa-solid fa-database me-2"></i>Доступ к базе</h2>\n      <p>Эта же SQL-база создаётся панелью для сервера #<?=$sidFilter?>. phpMyAdmin подключается к ней локально, без открытия MySQL в интернет.</p>\n    </div>\n    <span class="feature-chip <?=!empty($selectedSql[\'connected\'])?\'on\':\'off\'?>"><?=!empty($selectedSql[\'connected\'])?\'READY\':\'NOT READY\'?></span>\n  </div>\n\n  <?php if(!empty($selectedSql[\'connected\'])):?>\n  <div class="readonly-settings">\n    <div><small>Host для phpMyAdmin</small><b>127.0.0.1:3306</b></div>\n    <div><small>Database</small><b><?=e((string)($selectedSql[\'database\']??\'—\'))?></b></div>\n    <div><small>User</small><b id="sqlAccessUser"><?=e((string)($selectedSql[\'user\']??\'—\'))?></b></div>\n    <div class="span-2"><small>Password</small><div class="input-group mt-1"><input id="sqlAccessPass" class="form-control" type="password" readonly value="<?=e((string)($selectedSql[\'password\']??\'\'))?>"><button class="btn btn-soft" type="button" onclick="const p=document.getElementById(\'sqlAccessPass\');p.type=p.type===\'password\'?\'text\':\'password\'"><i class="fa-solid fa-eye"></i></button><button class="btn btn-soft" type="button" onclick="navigator.clipboard.writeText(document.getElementById(\'sqlAccessPass\').value)"><i class="fa-regular fa-copy"></i></button></div></div>\n  </div>\n\n  <div class="d-flex flex-wrap gap-2 mt-3">\n    <a class="btn btn-primary" href="/phpmyadmin/" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square me-2"></i>Открыть phpMyAdmin</a>\n    <button class="btn btn-soft" type="button" onclick="navigator.clipboard.writeText(document.getElementById(\'sqlAccessUser\').textContent.trim())"><i class="fa-regular fa-copy me-2"></i>Копировать логин</button>\n  </div>\n\n  <hr>\n  <div class="panel-head mb-2">\n    <div><h2 class="h5 mb-1">Внешнее подключение</h2><p class="mb-0">Нужно только для HeidiSQL / DBeaver / другого сервера. Для phpMyAdmin включать не надо.</p></div>\n    <span class="feature-chip <?=!empty($sqlExt[\'enabled\'])?\'on\':\'off\'?>"><?=!empty($sqlExt[\'enabled\'])?\'ENABLED\':\'DISABLED\'?></span>\n  </div>\n\n  <?php if(!empty($sqlExt[\'enabled\'])):?>\n    <div class="readonly-settings mb-3">\n      <div><small>External host</small><b><?=e((string)($sqlExt[\'public_host\']??\'—\'))?>:3306</b></div>\n      <div><small>Разрешённый IP</small><b><?=e((string)($sqlExt[\'remote_ip\']??\'—\'))?></b></div>\n      <div><small>MySQL TCP</small><b><?=!empty($sqlExt[\'listening\'])?\'LISTENING\':\'CHECK REQUIRED\'?></b></div>\n      <div><small>UFW</small><b><?=!empty($sqlExt[\'ufw_active\'])?\'ACTIVE\':\'NOT ACTIVE\'?></b></div>\n    </div>\n    <form method="post">\n      <?=csrf_field()?>\n      <input type="hidden" name="action" value="sql_external_disable">\n      <input type="hidden" name="id" value="<?=$sidFilter?>">\n      <button class="btn btn-danger"><i class="fa-solid fa-lock me-2"></i>Отключить внешний SQL</button>\n    </form>\n  <?php else:?>\n    <form method="post" class="row g-2 align-items-end">\n      <?=csrf_field()?>\n      <input type="hidden" name="action" value="sql_external_enable">\n      <input type="hidden" name="id" value="<?=$sidFilter?>">\n      <div class="col-md-8">\n        <label class="form-label">IPv4, с которого будешь подключаться</label>\n        <input class="form-control" name="remote_ip" placeholder="Например: 1.2.3.4" required pattern="(?:\\d{1,3}\\.){3}\\d{1,3}">\n      </div>\n      <div class="col-md-4">\n        <button class="btn btn-warning w-100"><i class="fa-solid fa-unlock-keyhole me-2"></i>Включить внешний SQL</button>\n      </div>\n    </form>\n  <?php endif;?>\n\n  <div class="alert alert-secondary mt-3 mb-0">\n    Внешний доступ создаёт MySQL-пользователя только для указанного IPv4. Если подключение идёт из интернета, на роутере также должен быть проброшен TCP/3306 на этот сервер. Для обычной работы через phpMyAdmin это не требуется.\n  </div>\n  <?php else:?>\n    <div class="alert alert-warning mb-0">Сначала нажми «Подключить / восстановить SQL» выше.</div>\n  <?php endif;?>\n</div>\n<?php endif;?>\n'

def patch_backend(p:Path):
    if not p.is_file():
        raise SystemExit(f"[PATCH ERROR] missing {p}")
    s=p.read_text(encoding="utf-8",errors="surrogateescape")

    if "# >>> HYPER-HOST SQL ACCESS PANEL v1 >>>" not in s:
        anchor="\ndef db_server_row("
        pos=s.find(anchor)
        if pos<0:
            anchor="\ndef server_config_set("
            pos=s.find(anchor)
        if pos<0:
            raise SystemExit(f"[PATCH ERROR] backend insert anchor missing in {p}")
        s=s[:pos]+"\n"+BACKEND+s[pos:]

    parser_anchor="q=sp.add_parser('sql-table'); q.add_argument('id',type=int); q.add_argument('table'); q.add_argument('--limit',type=int,default=100)"
    if "sp.add_parser('sql-external-status')" not in s:
        if parser_anchor not in s:
            raise SystemExit(f"[PATCH ERROR] sql-table parser anchor missing in {p}")
        repl=(parser_anchor+
              "\n    q=sp.add_parser('sql-external-status'); q.add_argument('id',type=int)"+
              "\n    q=sp.add_parser('sql-external-enable'); q.add_argument('id',type=int); q.add_argument('--remote',required=True)"+
              "\n    q=sp.add_parser('sql-external-disable'); q.add_argument('id',type=int)")
        s=s.replace(parser_anchor,repl,1)

    dispatch_anchor="elif args.cmd=='sql-table': result=sql_table(args.id,args.table,args.limit)"
    if "args.cmd=='sql-external-status'" not in s:
        if dispatch_anchor not in s:
            raise SystemExit(f"[PATCH ERROR] sql-table dispatch anchor missing in {p}")
        repl=(dispatch_anchor+
              "\n        elif args.cmd=='sql-external-status': result=sql_external_status(args.id)"+
              "\n        elif args.cmd=='sql-external-enable': result=sql_external_enable(args.id,args.remote)"+
              "\n        elif args.cmd=='sql-external-disable': result=sql_external_disable(args.id)")
        s=s.replace(dispatch_anchor,repl,1)

    p.write_text(s,encoding="utf-8",errors="surrogateescape")
    print("[OK] backend",p)

def patch_ui(p:Path):
    if not p.is_file():
        raise SystemExit(f"[PATCH ERROR] missing {p}")
    s=p.read_text(encoding="utf-8",errors="surrogateescape")

    if "if($action==='sql_external_enable')" not in s:
        anchor="        if($action==='server_power'){"
        pos=s.find(anchor)
        if pos<0:
            raise SystemExit(f"[PATCH ERROR] server_power POST anchor missing in {p}")
        s=s[:pos]+POSTS+"\n"+s[pos:]

    if "Доступ к базе" not in s:
        anchor='<div class="panel-card"><div class="panel-head"><div><h2>Таблицы самой сборки</h2>'
        pos=s.find(anchor)
        if pos<0:
            raise SystemExit(f"[PATCH ERROR] SQL tables card anchor missing in {p}")
        s=s[:pos]+CARD+"\n"+s[pos:]

    p.write_text(s,encoding="utf-8",errors="surrogateescape")
    print("[OK] ui",p)

patch_backend(src_ctl)
patch_backend(live_ctl)
patch_ui(src_ui)
patch_ui(live_ui)
